/**
 * Utility for exercising the boxing/parsing behavior of Java's primitive
 * wrapper classes (Integer, Long, Float, Double) over an array of inputs.
 *
 * Java has no native "unsigned" wrapper types, so unsigned semantics are
 * expressed via the static helpers provided on Integer/Long
 * (parseUnsignedInt, toUnsignedString, etc.).
 */
public final class WrapperMethodDemo {

    private WrapperMethodDemo() {
        // Utility class: prevent instantiation.
    }

    /**
     * Processes each element of the supplied array, invoking a family of
     * wrapper-class methods and printing the results.
     *
     * @param values the input values to process; must not be null and must
     *               not contain null elements
     * @throws NullPointerException if {@code values} or any element is null
     */
    public static void processValues(String[] values) {
        Objects.requireNonNull(values, "values array must not be null");

        for (int i = 0; i < values.length; i++) {
            String raw = values[i];
            Objects.requireNonNull(raw, "element at index " + i + " must not be null");

            // Validate and trim once; reject blank input defensively.
            String token = raw.trim();
            if (token.isEmpty()) {
                System.out.println("Index " + i + ": skipped (blank input)");
                continue;
            }

            System.out.println("Index " + i + " input: \"" + token + "\"");
            processInteger(token);
            processUnsignedInteger(token);
            processLong(token);
            processUnsignedLong(token);
            processFloat(token);
            processDouble(token);
            System.out.println("----------------------------------------");
        }
    }

