        try {
            int v = Integer.parseInt(token);
            System.out.println("  PInteger        -> " + v
                    + " (binary=" + Integer.toBinaryString(v)
                    + ", bitCount=" + Integer.bitCount(v) + ")");
        } catch (NumberFormatException e) {
            System.out.println("  PInteger        -> not a valid signed int");
        }
    }

    private static void processUnsignedInteger(String token) {
        try {
