        } catch (NumberFormatException e) {
            System.out.println("  PUnsignedInt    -> not a valid unsigned int");
        }
    }

    private static void processLong(String token) {
        try {
            long v = Long.parseLong(token);
            System.out.println("  PLong           -> " + v
                    + " (hex=" + Long.toHexString(v)
                    + ", bitCount=" + Long.bitCount(v) + ")");
        } catch (NumberFormatException e) {
            System.out.println("  PLong           -> not a valid signed long");
        }
    }

