        } catch (NumberFormatException e) {
            System.out.println("  PUnsignedLong   -> not a valid unsigned long");
        }
    }

    private static void processFloat(String token) {
        try {
            float v = Float.parseFloat(token);
            System.out.println("  PUnsignedFloat  -> " + v
                    + " (isFinite=" + Float.isFinite(v)
                    + ", abs=" + Math.abs(v) + ")");
        } catch (NumberFormatException e) {
            System.out.println("  PUnsignedFloat  -> not a valid float");
        }
    }

