        } catch (NumberFormatException e) {
            System.out.println("  PDouble         -> not a valid double");
        }
    }

    public static void main(String[] args) {
        String[] sample = {"42", "-17", "3.14159", "4294967295", "18446744073709551615"};
        processValues(sample);
    }
