                for (Integer neighbor : graph.neighbors(current)) {
                    traversedEdgeCount.incrementAndGet();
                    if (globallyVisited.add(neighbor)) {
                        visitedVertexCount.incrementAndGet();
                        queue.add(neighbor);
                    }
                }
            }
        }
