    public Object handleToken(final UserGroupInformation requester,
                              final Operation operation,
                              final String renewer,
                              final Token<DelegationTokenIdentifier> token) {

        Objects.requireNonNull(requester, "requester must not be null");
        Objects.requireNonNull(operation, "operation must not be null");

        final String shortName = requester.getShortUserName();
        if (shortName == null || shortName.trim().isEmpty()) {
            throw new IllegalArgumentException("Authenticated user name is missing");
        }

        try {
