                case CREATE:
                    return createToken(requester, renewer);
                case VERIFY:
                    return Boolean.valueOf(verifyToken(token));
                case RENEW:
                    return Boolean.valueOf(renewToken(requester, token));
                case CANCEL:
                    cancelToken(requester, token);
                    return Boolean.TRUE;
