                    + " failed for user " + shortName);
            throw new IllegalStateException(
                    "Delegation token operation failed: " + operation, e);
        }
    }

    private Token<DelegationTokenIdentifier> createToken(
            final UserGroupInformation requester, final String renewer)
            throws Exception {

        final String owner = requester.getShortUserName();
        final String effectiveRenewer =
                (renewer == null || renewer.trim().isEmpty()) ? owner : renewer.trim();

        final Token<DelegationTokenIdentifier> token =
                (Token<DelegationTokenIdentifier>) tokenManager.createToken(
                        requester, effectiveRenewer);
        if (token == null) {
            throw new IllegalStateException("Token manager returned a null token");
        }
        return token;
    }

    private boolean verifyToken(final Token<DelegationTokenIdentifier> token)
            throws Exception {
        requireToken(token);
        try {
            tokenManager.verifyToken(token);
            return true;
        } catch (final SecurityException e) {
            return false;
        }
    }

    private boolean renewToken(final UserGroupInformation requester,
                               final Token<DelegationTokenIdentifier> token)
            throws Exception {
        requireToken(token);
        final long expiry = tokenManager.renewToken(token, requester.getShortUserName());
        return expiry > System.currentTimeMillis();
    }

    private void cancelToken(final UserGroupInformation requester,
                             final Token<DelegationTokenIdentifier> token)
            throws Exception {
        requireToken(token);
        tokenManager.cancelToken(token, requester.getShortUserName());
    }

    private static void requireToken(final Token<DelegationTokenIdentifier> token) {
        if (token == null || token.getIdentifier() == null
